	if opts == nil || !opts.SkipAutoCategorize || !opts.AsDefaultPath || strings.TrimSpace(opts.Path) == "" {
		return "", nil
	}
	selectedPath := strings.TrimSpace(opts.Path)
	selectedPath, err := d.initDownloadPath(selectedPath)
	if err != nil {
		return "", err
	}
	return selectedPath, nil
}

